  ('Lammkoteletts (Neuseeland)', 'Butterzarte Lammkoteletts mit feinem Fettrand für optimalen Geschmack. Perfekt zum Grillen oder für die Pfanne.', 34.5, '/images/products/raw_lamb_chops.jpg', 'Lamm', 15, 'Neuseeland (Weideland)', 'LAMB-CHP-003', '4260192830036', array['Weideland', 'Grill', 'Zart']::text[], 2, 8, 21, 'active', 'public', array['/images/products/raw_lamb_chops.jpg']::text[], '2026-08-20T10:15:00.000Z', '2026-10-04T12:00:00.000Z', 'admin@freshtohome.de', 'admin@freshtohome.de'),
